const initialPlaces=()=>buildFloors().flatMap(f=>f.rooms.map((r,i)=>{
  let cat=r.category||({class:'classroom',staff:'staff',hr:'staff',hall:'hall',lab:'lab',cell:'cell'}[r.type]||'facility');
  let name=r.name;
  let type=r.type;
  // The supplied prototype requested computer labs on these floors, but room IDs are unverified.
  if((f.n===2||f.n===8)&&cat==='classroom'&&i===1){cat='lab';type='lab';name=`Computer Lab · ${floorName(f.n)}`;}
  if(f.n===7&&cat==='lab')name='Chemistry Lab';
  if(f.n===8&&cat==='cell')name='IEEE Student Branch Cell';
  return {id:`f${f.n}-${i}`,name,code:r.code||'',type,category:cat,floor:f.n,floorTitle:f.title,x:r.cx,y:r.cz,w:r.w,h:r.d,description:placeDescription(name,cat,f.n),building:'E-block',verified:false};
})).concat([{id:'main-entrance',name:'Main Entrance',code:'',type:'facility',category:'facility',floor:0,floorTitle:'Ground Floor',x:-7.8,y:0,w:.5,h:.5,building:'E-block',description:'Starting point for indicative routes within the E-block prototype map.',verified:false},{id:'b-block-drone-lab',name:'Drone Lab',code:'',type:'lab',category:'lab',floor:null,floorTitle:'B-block',x:null,y:null,w:null,h:null,building:'B-block',description:'B-block destination named in the supplied faculty note. The supplied indoor map only covers E-block; confirm the exact route on site.',verified:false}]);
function placeDescription(name,cat,floor){
 if(name.includes('Computer Lab'))return 'Computer laboratory destination requested in the supplied project notes. Exact room placement has not been verified.';
 if(cat==='lab'&&floor===7)return 'Chemistry laboratory destination shown on the supplied prototype floor map. Confirm the room on site.';
 if(cat==='cell')return 'Student cell destination shown on the supplied prototype floor map.';
 if(cat==='hall')return 'Hall destination shown on the supplied prototype floor map.';
 if(cat==='staff')return 'Staff-room location from supplied staff notes or prototype floor map.';
 return 'Mapped from the supplied project prototype; confirm current room details on site.';
}
