const seed = (key, value)=>{try{const stored=localStorage.getItem(key);return stored?JSON.parse(stored):value}catch{return value}};
const save=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
let places=seed(keys.places,initialPlaces());
let faculty=seed(keys.faculty,facultySeed);
let updates=seed(keys.updates,[]);
let sharedApiAvailable=false,sharedRevision=null,sharedSyncBusy=false;
let adminApiPassword=sessionStorage.getItem('sou_disha_admin_password')||'';
let currentUser=seed(keys.user,{role:'VISITOR',name:'Campus visitor',email:''});
const state={view:'home',floor:-1,category:'all',selected:null,routeStart:'',routeEnd:'',route:null,day:'Monday',eventTab:'all',adminTab:'overview'};
const floorList=buildFloors();
const placeById=id=>places.find(p=>p.id===id);
const codeSearch=q=>{const s=String(q||'').trim().toLowerCase();if(!s)return null;const parts=s.split('·').map(v=>v.trim());for(const part of parts){const c=part.replace(/^ea[- ]?/,'');const exact=places.find(p=>p.code&&p.code.toLowerCase()===part)||places.find(p=>p.code&&p.code.toLowerCase()===c);if(exact)return exact;}return places.find(p=>p.name.toLowerCase()===s)||places.find(p=>parts.some(v=>p.name.toLowerCase()===v))||places.find(p=>parts.some(v=>p.name.toLowerCase().startsWith(v)))||places.find(p=>parts.some(v=>p.name.toLowerCase().includes(v)));};
const floorLabel=n=>n===null||n===undefined?'B-block':n===0?'Ground':`Floor ${n}`;
const titleCat=c=>(categories.find(v=>v[0]===c)||['','Facilities'])[1];
const iconCat=c=>(categories.find(v=>v[0]===c)||['','','⌖'])[2];
const setToast=msg=>{const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(setToast.t);setToast.t=setTimeout(()=>e.classList.remove('show'),2600)};
function currentRole(){return currentUser?.role||'VISITOR'}
function isAdmin(){return currentRole()==='ADMIN'}
function isAcademic(){return ['STUDENT','FACULTY','ADMIN'].includes(currentRole())}
window.navigate=navigate;function navigate(view){if(view==='admin'&&!isAdmin()){setToast('Admin access is required.');return}if(view==='timetable'&&!isAcademic()){openLogin();setToast('Sign in as a student or faculty member to view the timetable.');return}state.view=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav-link[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#pageLabel').textContent=$(`#view-${view}`)?.dataset.title||'Overview';$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'});if(view==='map'){ensure3D();renderMap();}if(view==='directory')renderDirectory();if(view==='faculty')renderFaculty();if(view==='events')renderEvents();if(view==='timetable')renderTimetable();if(view==='admin')renderAdmin();}
function updateProfile(){const role=currentRole();const labels={VISITOR:'Visitor',STUDENT:'Student',FACULTY:'Faculty',ADMIN:'Administrator'};const names={VISITOR:'Campus visitor',STUDENT:currentUser.name||'Student',FACULTY:currentUser.name||'Faculty',ADMIN:currentUser.name||'Administrator'};const initials=role==='ADMIN'?'AD':role==='FACULTY'?'FC':role==='STUDENT'?'ST':'V';$('#roleLabel').textContent=labels[role];$('#roleAvatar').textContent=initials;$('#adminNav').classList.toggle('hidden',!isAdmin());$('#profileCard').innerHTML=`<div class="profile-mini"><span class="role-avatar">${initials}</span><span><b>${esc(names[role])}</b><small>${labels[role]} · local preview</small></span><button class="profile-logout" id="logoutBtn" title="Sign out">↗</button></div>`;$('#logoutBtn').onclick=()=>{currentUser={role:'VISITOR',name:'Campus visitor',email:''};save(keys.user,currentUser);updateProfile();navigate('home');setToast('Signed out. Browsing as a visitor.')};}
function fillSelects(){const cat=$('#categorySelect');cat.innerHTML='<option value="all">All categories</option>'+categories.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');$('#directoryFloor').innerHTML='<option value="all">All floors</option>'+Array.from({length:10},(_,i)=>`<option value="${i}">${floorLabel(i)}</option>`).join('');$('#placeOptions').innerHTML=places.filter(p=>p.floor!==null).map(p=>`<option value="${esc(p.name)}${p.code?` · ${esc(p.code)}`:''}"></option>`).join('');}
function renderLive(){const now=new Date();const active=updates.filter(u=>new Date(u.start)<=now&&new Date(u.end)>=now);const activeEvent=active.find(u=>u.kind==='event');const activeExam=active.find(u=>u.kind==='exam');const next=updates.filter(u=>new Date(u.start)>now).sort((a,b)=>new Date(a.start)-new Date(b.start));const content=(item,kind)=>item?`<div class="live-card"><span class="live-icon ${kind==='exam'?'exam':''}">${kind==='exam'?'▤':'◷'}</span><div class="live-copy"><span class="eyebrow">HAPPENING NOW · ${kind==='exam'?'EXAM':'EVENT'}</span><h3>${esc(item.title)}</h3><p>${esc(item.location||'Location to be confirmed')} · ends ${new Date(item.end).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</p></div><button class="live-card-link" data-view="events" aria-label="View update">↗</button></div>`:`<div class="live-card"><span class="live-icon ${kind==='exam'?'exam':''}">${kind==='exam'?'▤':'◷'}</span><div class="live-copy"><span class="eyebrow">${kind==='exam'?'EXAMS':'EVENTS'}</span><h3>${next.find(u=>u.kind===kind)?'Coming up':'No live update'}</h3><p class="live-empty">${next.find(u=>u.kind===kind)?`${esc(next.find(u=>u.kind===kind).title)} · ${new Date(next.find(u=>u.kind===kind).start).toLocaleDateString()}`:'No '+kind+' is published yet.'}</p></div><button class="live-card-link" data-view="events" aria-label="View updates">↗</button></div>`;
 $('#liveCards').innerHTML=content(activeEvent,'event')+content(activeExam,'exam');$('#liveCards').querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
 $('#homeCategories').innerHTML=categories.map(([id,label])=>`<button class="category-tile" data-category="${id}"><b>${iconCat(id)} &nbsp;${label}</b><small>${places.filter(p=>p.category===id).length} mapped places</small></button>`).join('');$('#homeCategories').querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;navigate('directory');$('#categorySelect').value=state.category;renderDirectory()});}
function renderFloors(){
 const choices=[[-1,'Campus'],[0,'G'],...Array.from({length:9},(_,i)=>[i+1,String(i+1)])];
 const routeFloors=state.route?.floors||[];
 $('#floorChips').innerHTML=choices.map(([n,label])=>`<button class="floor-chip ${state.floor===n?'active':''} ${routeFloors.includes(n)?'route-floor':''}" data-floor="${n}" title="${n<0?'Campus overview':floorName(n)}">${label}</button>`).join('');
 $('#floorChips').querySelectorAll('button').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.floor);if(state.route)clearRoute();state.floor=n;renderMap();});
}
function renderMap(){
 renderFloors();const fl=Number(state.floor);const floor=floorList.find(f=>f.n===fl);
 $('#mapFloorName').textContent=fl<0?'Campus · 3D view':floor?.title||floorName(fl);
 $('#mapFloorSub').textContent=fl<0?`Silver Oak campus · ${places.filter(p=>p.floor!==null).length} mapped destinations`:`Interactive 3D floor plan · E-block · ${places.filter(p=>p.floor===fl).length} mapped spaces`;
 if(window.Disha3D){if(window.Disha3D.currentFloor()!==fl)window.Disha3D.selectFloor(fl);if(!state.route)window.Disha3D.highlightCategory(state.category==='all'||state.category==='classroom'?null:state.category,fl>=0?fl:null);}
 $('#mapFilters').innerHTML=`<button class="filter-chip ${state.category==='all'?'active':''}" data-mapcat="all">All</button>`+categories.map(([id,label])=>`<button class="filter-chip ${state.category===id?'active':''}" data-mapcat="${id}">${label}</button>`).join('');$('#mapFilters').querySelectorAll('[data-mapcat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.mapcat;renderMap();});renderMapResults();
}
function renderMapResults(){const q=($('#mapSearch').value||'').toLowerCase();let list=places.filter(p=>(state.floor<0?p.floor!==null:p.floor===state.floor)&&((state.category==='all')||p.category===state.category)&&(!q||`${p.name} ${p.code} ${p.category}`.toLowerCase().includes(q))).slice(0,20);$('#mapResults').innerHTML=list.map(p=>`<button class="map-result-row" data-place="${esc(p.id)}"><span class="result-floor">${p.floor===null?'B':p.floor===0?'G':p.floor}</span><span><b>${esc(p.name)}</b><small>${esc(p.code||titleCat(p.category))} · ${titleCat(p.category)}</small></span><i>↗</i></button>`).join('')||'<div class="no-class">No matches in this view.</div>';$('#mapResults').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>selectPlace(b.dataset.place));}
function selectPlace(id){const p=placeById(id);if(!p)return;state.selected=id;if(p.floor!==null)state.floor=p.floor;$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');state.routeEnd=p.name;if(p.floor!==null)window.Disha3D?.focusRoom(p);renderMap();setToast(`${p.name} selected`);}
function routeLookup(query){return codeSearch(query)||null}
function findRoute(){const a=routeLookup($('#routeStart').value),b=routeLookup($('#routeEnd').value);if(!b){setToast('Choose a listed destination first.');return}if(!a){setToast('Choose a listed start point, such as a room or Main Entrance.');$('#routeStart').focus();return}if(b.floor===null){setToast('This destination is outside the mapped E-block floor plan.');showRouteMessage('Outside E-block map','The supplied prototype covers E-block only. Ask campus staff for cross-block directions.',null);return}if(!window.Disha3D){setToast('The 3D campus viewer is still loading. Please try again.');return}const alternatives=window.Disha3D.route(a,b);if(!alternatives){setToast('That room is not present in the supplied 3D floor model.');showRouteMessage('Room not in 3D model','Check the destination code or ask an administrator to update the floor map.',null);return}const keys=Object.keys(alternatives);const preferred=$('#stepFree').checked&&alternatives.lift?'lift':keys.sort((x,y)=>alternatives[x].minutes-alternatives[y].minutes)[0];const route=alternatives[preferred];state.route={startId:a.id,endId:b.id,floors:[a.floor,b.floor],method:preferred,alternatives};state.selected=b.id;state.floor=a.floor;window.Disha3D.showRoute(preferred);showRouteMessage(`3D route · ${preferred==='lift'?'Lift / step-free':preferred==='stairs'?'Stairs':'Walk'}`,`${route.meters} m · about ${route.minutes} min`,route.steps,alternatives,preferred);renderMap();}
function showRouteMessage(title,meta,steps,alternatives=null,selected=null){const box=$('#routeResult');box.classList.remove('hidden');const label=key=>key==='lift'?'Lift path · step-free':key==='stairs'?'Stair path':'Walk';const choices=alternatives?`<div class="route-alternatives" aria-label="Choose route">${Object.entries(alternatives).map(([key,r])=>`<button type="button" class="route-choice ${key===selected?'active':''}" data-route-view="${key}" aria-pressed="${key===selected}"><b>${label(key)}</b><small>${r.meters} m · about ${r.minutes} min</small></button>`).join('')}</div>`:'';const guidance=steps?`<div class="route-guide-title"><b>Follow these steps</b><small>Follow the selected ${selected==='lift'?'lift':'stair'} path and campus signs.</small></div><ol class="route-steps">${steps.map((step,i)=>{const text=step.text||step;const floor=step.floor===undefined?'':floorName(step.floor);const transfer=/lift|stairs/i.test(text);return `<li class="${transfer?'route-transfer':''}"><span class="route-step-number">${String(i+1).padStart(2,'0')}</span><span class="route-step-copy"><b>${esc(text)}</b>${floor?`<small>${esc(floor)}${transfer?' · transfer point':''}</small>`:''}</span></li>`}).join('')}</ol>`:'';box.innerHTML=`<h3>${esc(title)}</h3><div class="route-metrics"><span>${esc(meta||'')}</span></div>${choices}${guidance}<small class="route-disclaimer">The indoor route is simulated from the supplied sketch; follow on-site signs and verify accessibility before travel.</small>`;box.querySelectorAll('[data-route-view]').forEach(button=>button.onclick=()=>{const key=button.dataset.routeView;const route=state.route?.alternatives?.[key];if(!route)return;state.route.method=key;window.Disha3D?.showRoute(key);showRouteMessage(`3D route · ${label(key)}`,`${route.meters} m · about ${route.minutes} min`,route.steps,state.route.alternatives,key);renderFloors();});}
function clearRoute(){state.route=null;state.selected=null;window.Disha3D?.clearRoute();$('#routeResult').classList.add('hidden');$('#routeStart').value='';$('#routeEnd').value='';renderMap();}
let viewerLoading=false;
window.ensure3D=ensure3D;function ensure3D(){if(window.Disha3D||viewerLoading)return;viewerLoading=true;const status=$('#disha3dStatus');if(status){status.hidden=false;status.classList.remove('error');status.textContent='Loading the interactive 3D campus…';}import('/3d/map-3d.js?v=20261018fix').then(()=>{viewerLoading=false;if(!window.Disha3D){if(status){status.hidden=false;status.textContent='3D viewer loaded but failed to start. Open the browser console (F12) for details.';status.classList.add('error');}return;}if(status)status.hidden=true;try{window.dispatchEvent(new Event('resize'));}catch(e){}renderMap();}).catch(error=>{viewerLoading=false;console.error('SOU 3D DISHA viewer could not load:',error);if(status){status.hidden=false;status.textContent='The 3D model could not load: '+(error&&error.message?error.message:'unknown error')+'. Check network/WebGL, then reopen Map & directions.';status.classList.add('error');}});}
function setRouteStart(p){$('#routeStart').value=p.name+(p.code?` · ${p.code}`:'');}
function renderDirectory(){const q=($('#directorySearch').value||'').toLowerCase(),cat=$('#categorySelect').value||state.category||'all',fl=$('#directoryFloor').value;const list=places.filter(p=>(cat==='all'||p.category===cat)&&(fl==='all'||String(p.floor)===fl)&&`${p.name} ${p.code} ${p.description||''} ${p.building||''}`.toLowerCase().includes(q));$('#directoryCount').textContent=`${list.length} places`;$('#placeList').innerHTML=list.slice(0,200).map(p=>`<button class="place-card ${state.selected===p.id?'active':''}" data-place="${esc(p.id)}" data-cat="${esc(p.category)}"><span class="place-type-icon">${iconCat(p.category)}</span><span class="place-card-copy"><b>${esc(p.name)}</b><small>${esc(p.code?`${p.code} · `:'')}${esc(floorLabel(p.floor))} · ${titleCat(p.category)}</small></span><span class="place-arrow">↗</span></button>`).join('')||'<div class="empty-state"><span>⌕</span><h3>No matching places</h3><p>Try another room number, floor or category.</p></div>';$('#placeList').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>showPlaceDetail(b.dataset.place));}
function showPlaceDetail(id){const p=placeById(id);if(!p)return;state.selected=id;const card=$('#placeDetail');card.innerHTML=`<div class="detail-top"><span class="place-type-icon">${iconCat(p.category)}</span><div><h3>${esc(p.name)}</h3><small>${esc(titleCat(p.category))} · ${esc(floorLabel(p.floor))}</small></div><button class="icon-button detail-close" id="detailClose" aria-label="Close">×</button></div><div class="detail-attrs"><div class="detail-attr"><span>Room / code</span><b>${esc(p.code||'Not provided')}</b></div><div class="detail-attr"><span>Building</span><b>${esc(p.building||'E-block')}</b></div><div class="detail-attr"><span>Map status</span><b>${p.verified?'Verified':'Indicative · confirm on site'}</b></div></div><p style="font-size:9px;line-height:1.55;color:#718078">${esc(p.description||'No extra information provided.')}</p><div class="detail-actions"><button class="button button-primary" id="detailRoute">Directions ↗</button><button class="button button-outline" id="detailMap">View on map</button></div>`;$('#detailClose').onclick=()=>{card.innerHTML='<div class="empty-detail"><span>◎</span><b>Select a place</b><p>Details, floor and route actions will appear here.</p></div>'};$('#detailRoute').onclick=()=>{if(p.floor===null){setToast('Cross-block route not included in the E-block map.');return}navigate('map');$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');state.selected=p.id;state.floor=p.floor;renderMap()};$('#detailMap').onclick=()=>{if(p.floor===null){setToast('This place is outside the mapped E-block.');return}state.floor=p.floor;navigate('map');state.selected=p.id;renderMap()};renderDirectory();}
function renderFaculty(){const q=($('#facultySearch')?.value||'').toLowerCase();const list=faculty.filter(t=>`${t.name} ${t.initials} ${t.subject} ${t.staffRoom}`.toLowerCase().includes(q));if($('#facultySummary'))$('#facultySummary').innerHTML=`<div class="faculty-stat"><b>${faculty.length}</b><span>Faculty & staff profiles</span></div><div class="faculty-stat"><b>${new Set(faculty.map(t=>t.subject)).size}</b><span>Subjects represented</span></div><div class="faculty-stat"><b>${new Set(faculty.map(t=>t.staffRoom)).size}</b><span>Default locations</span></div>`;$('#facultyGrid').innerHTML=list.map(t=>`<div class="faculty-card"><span class="faculty-avatar">${esc(t.initials)}</span><span><b>${esc(t.name)}${t.honorific?` ${esc(t.honorific)}`:''}</b><small>${esc(t.subject)}<br>Default location: ${esc(t.staffRoom)}${isAcademic()?' · Schedule access enabled':''}</small></span><button data-teacher="${esc(t.id)}" title="Find teacher on map" aria-label="Find ${esc(t.name)} on the map">↗</button></div>`).join('')||'<div class="no-class">No faculty matches that search.</div>';$('#facultyGrid').querySelectorAll('[data-teacher]').forEach(b=>b.onclick=()=>{const t=faculty.find(x=>x.id===b.dataset.teacher);const p=places.find(x=>x.code===t.staffRoom)||placeById(t.staffPlace);if(p){if(p.floor!==null){navigate('map');state.selected=p.id;state.floor=p.floor;$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');renderMap();window.Disha3D?.focusRoom(p)}else setToast(`${t.name}: ${t.staffRoom}`)}else setToast(`${t.name} — ${t.staffRoom}`)});}
function renderTimetable(){if(!isAcademic())return;$('#dayTabs').innerHTML=Object.keys(timetable).map(d=>`<button class="day-tab ${state.day===d?'active':''}" data-day="${d}">${d.slice(0,3)}</button>`).join('');$('#dayTabs').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.day=b.dataset.day;renderTimetable()});$('#dayEyebrow').textContent=state.day.toUpperCase();$('#dayTitle').textContent=state.day;$('#timetableRows').innerHTML=timetable[state.day].map(([start,end,items])=>`<div class="time-row"><span class="time-slot">${start} – ${end}</span><div class="class-groups">${items.length?items.map(i=>`<div class="class-pill"><b>${esc(i.group?`${i.group} · `:'')}${esc(i.subject)}</b><small>${esc(i.room)}</small>${i.room.startsWith('EA-')?`<a href="#" data-room="${esc(i.room)}">Find room →</a>`:i.room.startsWith('D-')?`<small class="unmapped-room">Outside supplied E-block map</small>`:''}</div>`).join(''):'<span class="no-class">No class listed in supplied A1 timetable</span>'}</div></div>`).join('');$('#timetableRows').querySelectorAll('[data-room]').forEach(a=>a.onclick=e=>{e.preventDefault();const p=codeSearch(a.dataset.room);if(p){navigate('map');$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');state.selected=p.id;state.floor=p.floor;renderMap();window.Disha3D?.focusRoom(p)}else setToast(`${a.dataset.room} is not present in the supplied E-block schematic.`)});}
function dateStatus(u){const now=new Date(),s=new Date(u.start),e=new Date(u.end);return s<=now&&e>=now?'now':s>now?'upcoming':'past'}
function eventPlace(u){if(!u)return null;return places.find(p=>p.id===u.locationPlaceId)||places.find(p=>p.code&&u.locationCode&&p.code.toLowerCase()===String(u.locationCode).toLowerCase())||codeSearch(u.locationCode||u.location||'')||null;}
function focusMappedPlace(p,attempt=0){if(window.Disha3D){window.Disha3D.focusRoom(p);return}if(attempt<100)setTimeout(()=>focusMappedPlace(p,attempt+1),100);}
function locateUpdate(id){const u=updates.find(x=>x.id===id),p=eventPlace(u);if(!p||p.floor===null){setToast('This update has no mapped indoor room.');return}navigate('map');state.floor=p.floor;state.selected=p.id;state.category='all';state.route=null;$('#routeStart').value='Main Entrance';$('#routeEnd').value=`${p.name}${p.code?` · ${p.code}`:''}`;renderMap();focusMappedPlace(p);setToast(`Showing ${p.code||p.name} on the 3D map.`);}
async function pullSharedUpdates(){if(sharedSyncBusy)return false;sharedSyncBusy=true;try{const response=await fetch('/api/events',{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const payload=await response.json();if(!Array.isArray(payload.updates))throw new Error('Invalid event payload');sharedApiAvailable=true;const revision=String(payload.updatedAt||JSON.stringify(payload.updates));if(revision!==sharedRevision){sharedRevision=revision;updates=payload.updates;save(keys.updates,updates);renderEvents();renderLive();if(isAdmin())renderAdmin();}return true;}catch{sharedApiAvailable=false;if(isAdmin())renderAdmin();return false;}finally{sharedSyncBusy=false;}}
async function publishSharedUpdates(){save(keys.updates,updates);if(!sharedApiAvailable){setToast('Saved in this browser only. Start the updated ./run-local.sh server for shared event sync.');return false;}if(!isAdmin()||!adminApiPassword){setToast('Sign in again as administrator to publish shared events.');return false;}try{const response=await fetch('/api/events',{method:'PUT',headers:{'Content-Type':'application/json','Authorization':`Bearer ${adminApiPassword}`},body:JSON.stringify({updates})});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`HTTP ${response.status}`);sharedApiAvailable=true;sharedRevision=String(payload.updatedAt||JSON.stringify(payload.updates));updates=payload.updates;save(keys.updates,updates);renderEvents();renderLive();if(isAdmin())renderAdmin();setToast('Event update published for all visitors.');return true;}catch(error){sharedApiAvailable=false;if(isAdmin())renderAdmin();setToast(`Shared update failed: ${error.message}`);return false;}}
function renderEvents(){const active=updates.filter(u=>dateStatus(u)==='now');const next=updates.filter(u=>dateStatus(u)==='upcoming').sort((a,b)=>new Date(a.start)-new Date(b.start))[0];const b=$('#eventNowBanner');b.innerHTML=active.length?`<div><b>${active.length} campus update${active.length===1?'':'s'} happening now</b><small>${esc(active.map(u=>u.title).join(' · '))}</small></div><span class="status-pill">LIVE NOW</span>`:next?`<div><b>Next up · ${esc(next.title)}</b><small>${new Date(next.start).toLocaleString([], {weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(next.location||'Location to be confirmed')}</small></div><span class="status-pill">UPCOMING</span>`:`<div><b>No live campus updates</b><small>Event and exam notices will appear here when published.</small></div><span class="status-pill">CAMPUS UPDATES</span>`;const list=updates.filter(u=>state.eventTab==='all'||u.kind===state.eventTab).sort((a,b)=>new Date(a.start)-new Date(b.start));$('#eventsList').innerHTML=list.length?list.map(u=>{const d=new Date(u.start),p=eventPlace(u);return `<article class="event-card"><div class="event-date"><b>${d.toLocaleDateString([],{day:'2-digit'})}</b><small>${d.toLocaleDateString([],{month:'short'})}</small></div><div class="event-content"><h3>${esc(u.title)}</h3><p>${esc(u.details||'Details to be announced.')}</p><div class="event-meta"><span>${d.toLocaleString([],{weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(u.location||'Location TBA')}${u.locationNote?` · ${esc(u.locationNote)}`:''}</span>${p&&p.floor!==null?`<button class="event-locate" type="button" data-locate-update="${esc(u.id)}" aria-label="Locate ${esc(u.title)} on 3D map">Locate on 3D map <span>↗</span></button>`:''}</div></div><span class="event-type ${u.kind==='exam'?'exam':''}">${u.kind==='exam'?'EXAM':'EVENT'}</span></article>`}).join(''):'<div class="empty-state"><span>◷</span><h3>No updates in this view</h3><p>No event or exam details were supplied yet. Published updates created from the admin workspace will show up here automatically.</p></div>';$('#eventTabs').querySelectorAll('[data-event-tab]').forEach(t=>t.classList.toggle('active',t.dataset.eventTab===state.eventTab));$('#eventTabs').querySelectorAll('[data-event-tab]').forEach(t=>t.onclick=()=>{state.eventTab=t.dataset.eventTab;renderEvents()});$$('[data-locate-update]',$('#eventsList')).forEach(button=>button.onclick=()=>locateUpdate(button.dataset.locateUpdate));}
function renderAdmin(){if(!isAdmin())return;const mapped=places.filter(p=>p.floor!==null);const floors=Array.from({length:10},(_,i)=>({n:i,label:i===0?'G':String(i),count:mapped.filter(p=>p.floor===i).length}));const maxCount=Math.max(1,...floors.map(f=>f.count));const examCount=updates.filter(u=>u.kind==='exam').length,eventCount=updates.length-examCount;$('#adminMetrics').innerHTML=[[mapped.length,'Mapped destinations','E-block and entrance'],[faculty.length,'Faculty & staff','Directory records'],[updates.length,'Campus updates',`${eventCount} events · ${examCount} exams`],[`${floors.filter(f=>f.count>0).length}/10`,'Floors represented','Ground through 9th']].map(([n,label,sub])=>`<article class="admin-metric"><b>${n}</b><span>${label}</span><small>${sub}</small></article>`).join('');$('#adminFloorCoverage').innerHTML=floors.map(f=>`<div class="coverage-row"><span>${f.label}</span><div class="coverage-track"><i style="width:${Math.max(3,Math.round(f.count/maxCount*100))}%"></i></div><b>${f.count}</b></div>`).join('');$('#adminHealthSummary').innerHTML=`<div class="health-row"><i class="health-warn">!</i><span><b>Map accuracy</b><small>Indicative model; official plan still required</small></span></div><div class="health-row"><i class="health-ok">✓</i><span><b>Data storage</b><small>${sharedApiAvailable?'Shared event service · refreshes for all visitors':'Local-only mode · run ./run-local.sh for shared events'}</small></span></div><div class="health-row"><i class="health-info">i</i><span><b>Indoor coverage</b><small>E-block · 10 floor levels · routes simulated</small></span></div><div class="health-row"><i class="health-ok">✓</i><span><b>Role controls</b><small>Visitor, student/faculty and admin views</small></span></div>`;$('#adminTabs').querySelectorAll('[data-admin-tab]').forEach(t=>t.classList.toggle('active',t.dataset.adminTab===state.adminTab));$$('.admin-panel').forEach(p=>p.classList.toggle('active',p.id===`admin-${state.adminTab}`));$('#adminPlaceRecords').innerHTML=places.map(p=>recordRow(p.name,`${p.code||titleCat(p.category)} · ${floorLabel(p.floor)} · ${p.building||'E-block'}`,titleCat(p.category),p.id,'place')).join('')||emptyRecords();$('#adminFacultyRecords').innerHTML=faculty.map(t=>recordRow(t.name,`${t.initials} · ${t.subject} · ${t.staffRoom}`,'Teacher',t.id,'faculty')).join('')||emptyRecords();$('#adminUpdateRecords').innerHTML=updates.map(u=>recordRow(u.title,`${u.kind.toUpperCase()} · ${new Date(u.start).toLocaleString()} · ${u.location||'Location TBA'}`,u.kind==='exam'?'Exam':'Event',u.id,'update',true)).join('')||emptyRecords();$('#adminTabs').querySelectorAll('[data-admin-tab]').forEach(t=>t.onclick=()=>{state.adminTab=t.dataset.adminTab;renderAdmin()});$('#adminPlaceRecords').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editPlace(b.dataset.edit));$('#adminPlaceRecords').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deletePlace(b.dataset.delete));$('#adminFacultyRecords').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editFaculty(b.dataset.edit));$('#adminFacultyRecords').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteFaculty(b.dataset.delete));$('#adminUpdateRecords').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editUpdate(b.dataset.edit));$('#adminUpdateRecords').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteUpdate(b.dataset.delete));}
function recordRow(title,sub,kind,id,type,protectedItem=false){return `<div class="admin-record"><div class="admin-record-copy"><b>${esc(title)}</b><small>${esc(sub)}</small></div><span class="record-kind">${esc(kind)}</span><button class="record-action" data-edit="${esc(id)}">Edit</button><button class="record-action delete" data-delete="${esc(id)}" ${protectedItem?'disabled title="Admin-created updates cannot be deleted"':''}>${protectedItem?'Protected':'Remove'}</button></div>`}
function emptyRecords(){return '<div class="empty-state"><span>＋</span><h3>Nothing added yet</h3><p>Use the action above to create the first record.</p></div>'}
function modal(title,subtitle,inner,footer=''){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" data-backdrop><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">SOU 3D DISHA</span><h2>${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-close aria-label="Close">×</button></div>${inner}${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;root.querySelector('[data-close]').onclick=closeModal;root.querySelector('[data-backdrop]').onclick=e=>{if(e.target===e.currentTarget)closeModal()};}
function closeModal(){$('#modalRoot').innerHTML=''}
const destinationPhotos={'ieee-814':{roomCode:'814',floor:8,title:'IEEE Student Branch',image:'assets/ieee-student-branch.jpg',alt:'Silver Oak University IEEE Student Branch display',note:'IEEE Student Branch photo supplied for classroom EA-814.'},'aircraft-914':{roomCode:'914',floor:9,title:'Aircraft display',image:'assets/aeronautics-aircraft-room.jpg',alt:'Aircraft display in a Silver Oak classroom',note:'Pinned to classroom EA-914 as requested. The supplied photo visibly includes EA-904 signage; verify this room assignment before treating it as confirmed.'}};
function openPhotoPopup(photoId){const photo=destinationPhotos[photoId];if(!photo)return;const p=places.find(x=>x.code===photo.roomCode);modal(esc(photo.title),`Classroom EA-${esc(photo.roomCode)} · ${floorName(photo.floor)}`,`<div class="photo-viewer"><img src="${esc(photo.image)}" alt="${esc(photo.alt)}"><p>${esc(photo.note)}</p></div>`,`<button class="button button-light" data-close>Close</button><button class="button button-primary" id="photoRoute">Use EA-${esc(photo.roomCode)} as destination <span>→</span></button>`);$('#modalRoot').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#photoRoute').onclick=()=>{closeModal();if(!p){setToast(`EA-${photo.roomCode} is not in the current directory.`);return}navigate('map');state.selected=p.id;state.floor=p.floor;$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');renderMap();window.Disha3D?.focusRoom(p);$('#routeEnd').focus({preventScroll:true});};}
function exportBackup(){const data={product:'SOU 3D DISHA',schemaVersion:1,exportedAt:new Date().toISOString(),records:{places,faculty,updates}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`sou-3d-disha-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);setToast('JSON backup downloaded.');}
const roleAccounts=[{role:'STUDENT',name:'Aarav Patel',email:'student@sou.ac.in',password:'student123'},{role:'FACULTY',name:'Faculty member',email:'faculty@sou.ac.in',password:'faculty123'},{role:'ADMIN',name:'SOU Administrator',email:'admin@sou.ac.in',password:'admin123'}];
function openLogin(){const accounts=roleAccounts.map(a=>`<div class="demo-account"><span><b>${a.role==='ADMIN'?'Administrator':a.role==='FACULTY'?'Faculty':'Student'}</b><small>${a.email}</small></span><button data-fill="${a.role}">Use demo</button></div>`).join('');modal('Sign in to SOU 3D DISHA','Visitor access is open. Sign in to unlock the A1 timetable or admin tools.',`<form id="loginForm"><div class="form-grid"><div class="form-field full"><label>EMAIL</label><input name="email" type="email" required placeholder="name@sou.ac.in"></div><div class="form-field full"><label>PASSWORD</label><input name="password" type="password" required placeholder="Enter your password"></div></div><button class="button button-primary full-width" type="submit">Sign in <span>→</span></button></form><div class="demo-accounts"><span class="eyebrow">LOCAL DEMO ACCOUNTS</span>${accounts}</div><div class="demo-warning">These sample credentials run entirely in your browser and are not real university accounts. Replace with a secure backend before deployment.</div>`);$('#loginForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);attemptLogin(fd.get('email'),fd.get('password'))};$$('[data-fill]').forEach(b=>b.onclick=()=>{const a=roleAccounts.find(x=>x.role===b.dataset.fill);$('#loginForm [name=email]').value=a.email;$('#loginForm [name=password]').value=a.password;attemptLogin(a.email,a.password)});}
function attemptLogin(email,password){const a=roleAccounts.find(x=>x.email===email&&x.password===password);if(!a){setToast('That email or password does not match a local demo account.');return}currentUser={role:a.role,name:a.name,email:a.email};save(keys.user,currentUser);if(a.role==='ADMIN'){adminApiPassword=password;sessionStorage.setItem('sou_disha_admin_password',password)}else{adminApiPassword='';sessionStorage.removeItem('sou_disha_admin_password')}closeModal();updateProfile();renderLive();if(a.role==='ADMIN')navigate('admin');else if(a.role==='STUDENT'||a.role==='FACULTY')navigate('timetable');setToast(`Signed in as ${a.role.toLowerCase()} demo.`)}
function addForm(type,existing={}){const editing=!!existing.id;let heading=editing?'Edit':'Add';let body='';const selectedEventPlace=type==='update'?eventPlace(existing):null;if(type==='place'){body=`<form id="recordForm"><div class="form-grid"><div class="form-field full"><label>DESTINATION NAME</label><input name="name" required value="${esc(existing.name||'')}"></div><div class="form-field"><label>ROOM / CODE</label><input name="code" value="${esc(existing.code||'')}"></div><div class="form-field"><label>CATEGORY</label><select name="category">${categories.map(c=>`<option value="${c[0]}" ${existing.category===c[0]?'selected':''}>${c[1]}</option>`).join('')}</select></div><div class="form-field"><label>FLOOR</label><select name="floor"><option value="none" ${existing.floor===null?'selected':''}>Outside mapped floors</option>${Array.from({length:10},(_,i)=>`<option value="${i}" ${existing.floor===i?'selected':''}>${floorLabel(i)}</option>`).join('')}</select></div><div class="form-field"><label>BUILDING</label><input name="building" value="${esc(existing.building||'E-block')}"></div><div class="form-field full"><label>PUBLIC DESCRIPTION</label><textarea name="description">${esc(existing.description||'')}</textarea></div></div></form>`}
 if(type==='faculty'){body=`<form id="recordForm"><div class="form-grid"><div class="form-field"><label>FULL NAME</label><input name="name" required value="${esc(existing.name||'')}"></div><div class="form-field"><label>INITIALS</label><input name="initials" required value="${esc(existing.initials||'')}"></div><div class="form-field full"><label>SUBJECT / DEPARTMENT</label><input name="subject" required value="${esc(existing.subject||'')}"></div><div class="form-field"><label>DEFAULT LOCATION</label><input name="staffRoom" required value="${esc(existing.staffRoom||'')}"></div><div class="form-field"><label>HONORIFIC (OPTIONAL)</label><input name="honorific" value="${esc(existing.honorific||'')}"></div></div></form>`}
 if(type==='update'){const mapped=places.filter(p=>p.floor!==null).sort((a,b)=>a.floor-b.floor||String(a.code||a.name).localeCompare(String(b.code||b.name)));const roomOptions=Array.from({length:10},(_,floor)=>{const list=mapped.filter(p=>p.floor===floor);return list.length?`<optgroup label="${esc(floorLabel(floor))}">${list.map(p=>`<option value="${esc(p.id)}" ${selectedEventPlace?.id===p.id?'selected':''}>${esc(p.code||p.name)} — ${esc(p.name)}</option>`).join('')}</optgroup>`:''}).join('');body=`<form id="recordForm"><div class="form-grid"><div class="form-field full"><label>TITLE</label><input name="title" required value="${esc(existing.title||'')}"></div><div class="form-field"><label>TYPE</label><select name="kind"><option value="event" ${existing.kind==='event'?'selected':''}>Event</option><option value="exam" ${existing.kind==='exam'?'selected':''}>Exam</option></select></div><div class="form-field full"><label>MAP LOCATION / ROOM</label><select name="placeId"><option value="">No mapped room selected</option>${roomOptions}</select><small>Choose a mapped room by its code, such as 511 or 601. Visitors can open it on the 3D map.</small></div><div class="form-field"><label>OTHER LOCATION (OPTIONAL)</label><input name="location" placeholder="e.g. Main auditorium" value="${esc(selectedEventPlace?'':(existing.location||''))}"></div><div class="form-field"><label>LOCATION NOTE (OPTIONAL)</label><input name="locationNote" placeholder="Building, entrance or extra detail" value="${esc(existing.locationNote||'')}"></div><div class="form-field"><label>START</label><input name="start" type="datetime-local" required value="${esc(existing.start||'')}"></div><div class="form-field"><label>END</label><input name="end" type="datetime-local" required value="${esc(existing.end||'')}"></div><div class="form-field full"><label>DETAILS / PUBLIC INFORMATION</label><textarea name="details">${esc(existing.details||'')}</textarea></div></div></form>`}
 modal(`${heading} ${type==='place'?'destination':type==='faculty'?'teacher':'event / exam'}`,type==='update'?'Mapped event locations sync to visitors when the shared server is running.':'Keep other changes local to this browser.',body,`<small>${type==='update'?'Shared event changes publish to the running server.':'Other directory changes remain local to this browser.'}</small><button class="button button-primary" id="saveRecord">${editing?'Save changes':'Create record'} <span>→</span></button>`);$('#saveRecord').onclick=()=>{const form=$('#recordForm');if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));if(type==='place'){let p={...existing,id:existing.id||`custom-${Date.now()}`,name:d.name,code:d.code.trim(),category:d.category,type:d.category,floor:d.floor==='none'?null:Number(d.floor),floorTitle:d.floor==='none'?'Outside mapped floors':floorName(Number(d.floor)),building:d.building||'E-block',description:d.description||'',verified:false};if(!existing.id){p.x=p.floor===null?null:-3;p.y=p.floor===null?null:0;p.w=p.floor===null?null:1.1;p.h=p.floor===null?null:1.1;places.unshift(p)}else Object.assign(existing,p);save(keys.places,places)}else if(type==='faculty'){const f={...existing,id:existing.id||`custom-t-${Date.now()}`,name:d.name,initials:d.initials.toUpperCase(),subject:d.subject,staffRoom:d.staffRoom,honorific:d.honorific};if(existing.id)faculty=faculty.map(x=>x.id===existing.id?f:x);else faculty.push(f);save(keys.faculty,faculty)}else{if(new Date(d.end)<=new Date(d.start)){setToast('End time must be after start time.');return}const mapped=places.find(p=>p.id===d.placeId)||null;const customLocation=(d.location||'').trim();const u={...existing,id:existing.id||`update-${Date.now()}`,title:d.title,kind:d.kind,location:mapped?`${mapped.name}${mapped.code?` · ${mapped.code}`:''} · ${floorLabel(mapped.floor)}`:customLocation,locationNote:(d.locationNote||'').trim(),locationPlaceId:mapped?.id||'',locationCode:mapped?.code||'',locationFloor:mapped?.floor??null,start:d.start,end:d.end,details:d.details,createdBy:'ADMIN'};if(existing.id)updates=updates.map(x=>x.id===existing.id?u:x);else updates.push(u);save(keys.updates,updates)}closeModal();fillSelects();renderAdmin();renderEvents();renderLive();if(type==='update'){void publishSharedUpdates();}else setToast(editing?'Record updated.':'Record created.');};}
function editPlace(id){const p=placeById(id);if(p)addForm('place',{...p})}function editFaculty(id){const t=faculty.find(x=>x.id===id);if(t)addForm('faculty',{...t})}function editUpdate(id){const u=updates.find(x=>x.id===id);if(u)addForm('update',{...u})}
function deletePlace(id){if(!confirm('Remove this destination from the local directory?'))return;places=places.filter(p=>p.id!==id);save(keys.places,places);fillSelects();renderAdmin();renderLive();setToast('Destination removed.')}
function deleteFaculty(id){if(!confirm('Remove this person from the local directory?'))return;faculty=faculty.filter(p=>p.id!==id);save(keys.faculty,faculty);renderAdmin();renderFaculty();setToast('Directory record removed.')}
function deleteUpdate(id){const u=updates.find(x=>x.id===id);if(u?.createdBy==='ADMIN'){setToast('Admin-created events and exams cannot be deleted; edit the information instead.');return}if(!confirm('Remove this update?'))return;updates=updates.filter(x=>x.id!==id);save(keys.updates,updates);renderAdmin();renderEvents();renderLive();void publishSharedUpdates()}
function globalSearch(){const q=$('#globalSearch').value.trim().toLowerCase();const box=$('#globalResults');if(!q){box.classList.add('hidden');return}let ps=places.filter(p=>`${p.name} ${p.code} ${p.category}`.toLowerCase().includes(q)).slice(0,5);let ts=faculty.filter(t=>`${t.name} ${t.initials} ${t.subject}`.toLowerCase().includes(q)).slice(0,3);box.innerHTML=[...ps.map(p=>`<button class="global-result" data-place="${esc(p.id)}"><span class="global-result-icon">${iconCat(p.category)}</span><span><b>${esc(p.name)}</b><small>${esc(p.code||titleCat(p.category))} · ${floorLabel(p.floor)}</small></span></button>`),...ts.map(t=>`<button class="global-result" data-teacher="${esc(t.id)}"><span class="global-result-icon">♙</span><span><b>${esc(t.name)}</b><small>${esc(t.subject)} · staff room ${esc(t.staffRoom)}</small></span></button>`)].join('')||'<div class="no-class" style="padding:10px">No matches found.</div>';box.classList.remove('hidden');box.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{box.classList.add('hidden');$('#globalSearch').value='';navigate('directory');showPlaceDetail(b.dataset.place)});box.querySelectorAll('[data-teacher]').forEach(b=>b.onclick=()=>{box.classList.add('hidden');$('#facultySearch').value=faculty.find(t=>t.id===b.dataset.teacher).name;navigate('faculty');renderFaculty()});}
function openMapForQuery(query){state.category='all';navigate('map');$('#mapSearch').value=query;renderMap();}
