 $('#roleButton').onclick=openLogin;$('#mobileMenu').onclick=()=>{$('#sidebar').classList.add('open');$('#mobileOverlay').classList.add('show')};$('#mobileOverlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show')};
 $('#directorySearch').oninput=renderDirectory;$('#categorySelect').onchange=()=>{state.category=$('#categorySelect').value;renderDirectory()};$('#directoryFloor').onchange=renderDirectory;$('#facultySearch').oninput=renderFaculty;$('#exportBackup').onclick=exportBackup;$('#globalSearch').oninput=globalSearch;$('#globalSearch').onfocus=()=>{if(window.innerWidth<600)$('#globalSearch').parentElement.classList.add('search-open');globalSearch()};document.addEventListener('click',e=>{if(!e.target.closest('.global-search')){$('#globalResults').classList.add('hidden');$('.global-search').classList.remove('search-open')}});
 $('#routeStart').value='Main Entrance';$('#setEntrance').onclick=()=>{$('#routeStart').value='Main Entrance';setToast('Start point set to the E-block main entrance.')};$('#findRoute').onclick=findRoute;$('#clearRoute').onclick=clearRoute;$('#resetMap').onclick=()=>{state.floor=-1;state.category='all';$('#mapSearch').value='';clearRoute();window.Disha3D?.resetView();renderMap();setToast('3D campus view reset.')};$('#mapSearch').oninput=renderMap;$('#zoomToggle').onclick=()=>window.Disha3D?.recenter();$('#useGps').onclick=()=>{if(!navigator.geolocation){setToast('Location services are not available in this browser.');return}navigator.geolocation.getCurrentPosition(pos=>{setToast('Outdoor GPS received. Choose your indoor room or use the E-block entrance as a starting point; GPS cannot identify floors or rooms.')},()=>setToast('Location permission was unavailable. Enter your current indoor room or starting point manually.'),{timeout:7000,maximumAge:60000})};
