 window.addEventListener('soumap',e=>{if(e.detail?.type==='photo'){openPhotoPopup(e.detail.photoId);return}if(e.detail?.type!=='room')return;const m=String(e.detail.id||'').match(/^(\d+)-(\d+)$/);if(!m)return;const p=placeById(`f${m[1]}-${m[2]}`);if(!p)return;state.selected=p.id;state.floor=p.floor;$('#routeEnd').value=p.name+(p.code?` · ${p.code}`:'');state.routeEnd=p.name;if(state.view==='map')renderMapResults();});$('#eventTabs').querySelectorAll('[data-event-tab]').forEach(b=>b.onclick=()=>{state.eventTab=b.dataset.eventTab;renderEvents()});$$('[data-action="manage-events"]').forEach(b=>b.onclick=()=>{navigate('admin');state.adminTab='updates';renderAdmin()});$('#adminTabs').querySelectorAll('[data-admin-tab]').forEach(t=>t.onclick=()=>{state.adminTab=t.dataset.adminTab;renderAdmin()});$$('[data-action="add-place"]').forEach(b=>b.onclick=()=>addForm('place'));$$('[data-action="add-faculty"]').forEach(b=>b.onclick=()=>addForm('faculty'));$$('[data-action="add-update"]').forEach(b=>b.onclick=()=>addForm('update'));
