function roomSupportsInterior(p){
  if(!p)return false;
  const code=String(p.code||'').replace(/^EA-?/i,'');
  return p.floor===5&&['511','512','513'].includes(code);
}
function syncInteriorButton(){try{const p0=places.find(x=>x.id===state.selected);if(p0)window.__siliSelectedRoom={...p0,code:p0.code,floor:p0.floor};}catch(e){}
  let btn=$('#enterRoomViewBtn');
  if(!btn){
    const host=$('#routeResult')||$('.map-side')||$('#view-map');
    if(!host)return;
    btn=document.createElement('button');
    btn.type='button';
    btn.id='enterRoomViewBtn';
    btn.className='btn primary';
    btn.style.cssText='margin:8px 0;width:100%;display:none';
    btn.textContent='Enter classroom 3D view';
    host.prepend(btn);
    btn.onclick=()=>{
      const p=places.find(x=>x.id===state.selected)||routeLookup($('#routeEnd')?.value||'');
      if(!p){setToast('Select classroom 511, 512 or 513 first.');return;}
      const ok=window.Disha3D?.enterRoomView?.(p);
      if(ok){
        btn.textContent='Exit classroom view';
        btn.dataset.mode='exit';
        setToast('Classroom interior · EA wing floor 5');
      }else if(btn.dataset.mode==='exit'){
        window.Disha3D?.exitRoomView?.();
        btn.textContent='Enter classroom 3D view';
        btn.dataset.mode='enter';
      }else setToast('Interior view is available only for rooms 511, 512 and 513 on floor 5.');
    };
  }
  const p=places.find(x=>x.id===state.selected);
  const interiorOn=window.Disha3D?.isInteriorActive?.();
  if(interiorOn){
    btn.style.display='block';
    btn.textContent='Exit classroom view';
    btn.dataset.mode='exit';
  }else if(roomSupportsInterior(p)){
    btn.style.display='block';
    btn.textContent=`Enter classroom ${p.code} · 3D view`;
    btn.dataset.mode='enter';
  }else{
    btn.style.display='none';
    btn.dataset.mode='enter';
  }
}

